select a.id BORKEN_ID,a.ALARM_STATE borken_alarm_state,a.status as alarm_status,

a.content borken_content,d.broken_record_id list_id,a.TITLE as title,A.ALARM_LEVEL AS ALARM_LEVEL,
d.solve_status,
d.opinion list_opinion,d.create_time list_createTime,d.creator list_creator
from (
select alarm_info.*,asset.name,asset.asset_mode from alarm_info,asset where alarm_info.asset_id=asset.id

    and asset.asset_mode = #{assetMode}

) a
left join
(select b.alarm_id,b.status as solve_status, c.* from BROKEN_RECORD b
left join BROKEN_RECORD_OPINION c on b.id=c.BROKEN_RECORD_ID) d on a.id=d.alarm_id
where rownum < 20000

    and a.org_id = #{orgId}


    and a.org_id in

        #{id}



    and REGEXP_INSTR(a.asset_ip, #{assetIp})>0


    and REGEXP_INSTR(a.name, #{assetName})>0


    and REGEXP_INSTR(a.TITLE, #{title})>0


    and a.status = #{status}


    and a.alarm_code = #{eventCategory}


    and a.alarm_level = #{alarmLevel}


    and a.type = #{type}


    and a.occur_time between #{startTime} and #{endTime}


    and a.asset_mode = #{assetMode}

order by a.occur_time desc

